func retryableStatus(code int) bool {
	switch code {
	case http.StatusRequestTimeout,
		http.StatusTooEarly,

		http.StatusTooManyRequests:
		return true
	}

	return code >= 500
}

func retryableError(err error) bool {

if err == nil {
	return false
}

if errors.Is(err, context.Canceled) ||
	errors.Is(err, context.DeadlineExceeded) {
	return false
}

var ne net.Error

if errors.As(err, &ne) {
	return true
}

msg := strings.ToLower(err.Error())

	return strings.Contains(msg, "eof") ||
		strings.Contains(msg, "connection reset") ||
		strings.Contains(msg, "broken pipe") ||
		strings.Contains(msg, "connection refused")
}

func retryableErrorWithContext(ctx context.Context, err error) bool {

if err == nil {
	return false
}
if ctx != nil && ctx.Err() != nil {
	return false
}
// A transport/client timeout is transient while the parent operation
// still has budget. Parent cancellation/deadline always wins.

var ne net.Error
if errors.As(err, &ne) && ne.Timeout() {
	return true
}
if errors.Is(err, context.DeadlineExceeded) {
	return true
}
return retryableError(err)

}

func (s *ResilientSession) login(
	ctx context.Context,
) error {
	s.loginMu.Lock()
	defer s.loginMu.Unlock()

	return s.Client.Login(ctx)
}

func (s *ResilientSession) delay(
	ctx context.Context,
	attempt int,
) error {
	p := s.Policy

if p.BaseDelay <= 0 {
	p.BaseDelay = 120 * time.Millisecond
}

if p.MaxDelay <= 0 {
	p.MaxDelay = 1500 * time.Millisecond
}

delay := p.BaseDelay

for i := 1; i < attempt; i++ {
	delay *= 2

	if delay >= p.MaxDelay {
		delay = p.MaxDelay

		break
	}
}

jitterMax := delay / 4

var jitter time.Duration

if jitterMax > 0 {
	jitter = time.Duration(
		rand.Int63n(
			int64(jitterMax) + 1,
		),
	)
}

timer := time.NewTimer(
	delay + jitter,
)
defer timer.Stop()

select {
case <-ctx.Done():
	return ctx.Err()

	case <-timer.C:
		return nil
	}
}

